import{NATURE_SOUNDS,NATURE_MAX_VOLUME,NATURE_DEFAULT_VOLUME,createQuranNatureAudio}from './quran-nature-audio.js';
import{read,write}from './storage.js';
import{mountNatureMotion}from './quran-nature-motion.js';
import{t,translateUi,subscribeLanguage}from './i18n.js';
export function mountQuranPlayerExtras(panel,{playback,ruqyah,createNature=createQuranNatureAudio,doc=document,win=window}={}){
 const root=doc.createElement('section');root.className='quran-player-extras';root.setAttribute('data-i18n-aria-label','player.extrasLabel');root.setAttribute('aria-label',t('player.extrasLabel'));
 const clock='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="13" r="8"/><path d="M12 9v4l3 2M9 2h6"/></svg>',drop='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3C8 9 5 11 5 15a7 7 0 0 0 14 0c0-4-3-6-7-12ZM9 16a3 3 0 0 0 3 3"/></svg>';
 root.innerHTML='<div class="quran-extras-actions"><button type="button" data-extra="timer" aria-expanded="false" aria-controls="quran-sleep-options">'+clock+'<span data-timer-label>Таймер</span></button><button type="button" data-extra="nature" aria-expanded="false" aria-controls="quran-nature-options">'+drop+'<span data-i18n="player.nature">Фон природы</span></button></div><fieldset id="quran-sleep-options" hidden><legend data-i18n="player.stopReading">Остановить чтение</legend><div class="quran-extra-choices">'+[[15,'15 мин'],[30,'30 мин'],[45,'45 мин'],[60,'60 мин'],['end','До конца суры'],['off','Выключен']].map(([value,title])=>'<button type="button" data-sleep="'+value+'" aria-pressed="false">'+title+'</button>').join('')+'</div><p class="quran-extra-note" data-i18n="player.timerNote">Таймер продолжает отсчёт во время паузы.</p></fieldset><fieldset id="quran-nature-options" hidden><legend data-i18n="player.natureBalance">Баланс фона с чтением</legend><div class="quran-extra-choices"><button type="button" data-nature="off" data-i18n="player.off" aria-pressed="true">Выключен</button>'+NATURE_SOUNDS.map(sound=>'<button type="button" data-nature="'+sound.id+'" data-i18n="player.'+sound.id+'" aria-pressed="false">'+sound.name+'</button>').join('')+'</div><div class="quran-nature-visual" role="group" data-i18n-aria-label="player.wallpaperLabel" aria-label="Обои плеера"><span data-i18n="player.wallpaper">Обои</span><div class="quran-extra-choices"><button type="button" data-nature-visual="video" data-i18n="player.video" aria-pressed="true">Видео</button><button type="button" data-nature-visual="photo" data-i18n="player.photo" aria-pressed="false">Фото</button></div></div><label class="quran-nature-volume"><span data-i18n="player.volume">Громкость фона</span> <output data-nature-volume dir="ltr"></output><input type="range" min="0" max="'+NATURE_MAX_VOLUME+'" step="1" dir="ltr" data-i18n-aria-label="player.natureVolume" aria-label="Громкость фона природы"></label><p class="quran-extra-note" data-i18n="player.volumeNote">Общая громкость — кнопками телефона, баланс фона — этим ползунком.</p><p class="quran-extra-note" data-nature-status role="status"></p></fieldset>';
 panel.append(root);let disposed=false,lastStopped=true;
 function drawVisual(value){panel.dataset.natureVisual=value==='photo'?'photo':'video';for(const button of root.querySelectorAll('[data-nature-visual]'))button.setAttribute('aria-pressed',String(button.dataset.natureVisual===panel.dataset.natureVisual));}
 drawVisual(read('quran-nature-visual','video'));const motion=mountNatureMotion(panel,{doc,win});
 const nature=createNature({volume:read('quran-nature-volume',NATURE_DEFAULT_VOLUME)}),volume=root.querySelector('input');volume.value=String(nature.state.volume);let lastNatureState=nature.state;const preferred=read('quran-nature-kind',null);if(NATURE_SOUNDS.some(sound=>sound.id===preferred))void nature.select(preferred);
 function drawTimer(){const timer=playback.state.sleepTimer||{mode:null},label=root.querySelector('[data-timer-label]'),text=timer.mode==='end'?t('player.timerEndSurah'):timer.mode?Math.floor(timer.remaining/60)+':'+String(timer.remaining%60).padStart(2,'0'):t('player.timer');label.textContent=text;label.dir=timer.mode&&timer.mode!=='end'?'ltr':'auto';root.querySelector('[data-extra=timer]').setAttribute('aria-label',timer.mode===null?t('player.timerOff'):timer.mode==='end'?text:t('player.timer')+' '+text);for(const button of root.querySelectorAll('[data-sleep]'))button.setAttribute('aria-pressed',String(button.dataset.sleep===(timer.mode===null?'off':String(timer.mode))));}
 function sync(){if(disposed)return;const state=playback.state;root.hidden=!!ruqyah.state.record;drawTimer();const stopped=!state.surah||state.status==='stopped',clear=stopped&&!lastStopped;lastStopped=stopped;if(clear){write('quran-nature-kind',null);void nature.select(null);}void nature.sync(!ruqyah.state.record&&state.status==='playing');}
 function drawNatureText(state){const selected=!ruqyah.state.record&&NATURE_SOUNDS.find(sound=>sound.id===state.kind),label=panel.querySelector('[data-nature-label]');if(label){label.textContent=selected?t('player.'+selected.id):'';label.hidden=!selected;}const status=state.loading?'player.natureLoading':!state.supported?'player.natureUnsupported':state.error?'player.natureFailed':state.systemPaused?'player.natureSystemPaused':state.kind?state.playing?'player.naturePlaying':'player.naturePending':'player.natureChoose';root.querySelector('[data-nature-status]').textContent=t(status);}
 const offNature=nature.subscribe(state=>{lastNatureState=state;volume.value=String(state.volume);for(const button of root.querySelectorAll('[data-nature]'))button.setAttribute('aria-pressed',String(button.dataset.nature===(state.kind||'off')));root.querySelector('[data-nature-volume]').textContent=state.volume+'%';const selected=!ruqyah.state.record&&NATURE_SOUNDS.find(sound=>sound.id===state.kind);if(selected)panel.dataset.nature=selected.id;else delete panel.dataset.nature;drawNatureText(state);});
 const paintLanguage=()=>{translateUi(root);for(const button of root.querySelectorAll('[data-sleep]')){const value=button.dataset.sleep;button.textContent=value==='off'?t('player.off'):value==='end'?t('player.timerEndSurah'):t('player.timerMinutes',{count:Number(value)});}drawTimer();drawNatureText(lastNatureState);};const stopLanguage=subscribeLanguage(paintLanguage);paintLanguage();
 root.onclick=event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.extra){const area=root.querySelector(button.dataset.extra==='timer'?'#quran-sleep-options':'#quran-nature-options'),opening=area.hidden;for(const field of root.querySelectorAll('fieldset'))field.hidden=true;for(const toggle of root.querySelectorAll('[data-extra]'))toggle.setAttribute('aria-expanded','false');area.hidden=!opening;button.setAttribute('aria-expanded',String(opening));}else if(button.dataset.sleep){const value=button.dataset.sleep;playback.setSleepTimer(value==='off'?null:value==='end'?'end':Number(value));drawTimer();}else if(button.dataset.natureVisual){const value=button.dataset.natureVisual;if(value!=='photo'&&value!=='video')return;drawVisual(value);write('quran-nature-visual',value);motion.sync();}else if(button.dataset.nature){const selected=button.dataset.nature==='off'?null:button.dataset.nature;write('quran-nature-kind',selected);void nature.select(selected);}};
 volume.oninput=()=>void nature.setVolume(Number(volume.value));volume.onchange=()=>{write('quran-nature-volume',Number(volume.value));};
 const gesture=event=>{if(event.isTrusted&&nature.state.kind&&event.target.closest('[data-toggle]'))void nature.unlock();},resume=()=>{playback.checkSleepTimer();if(!doc.hidden&&nature.state.kind&&playback.state.status==='playing')void nature.unlock();};
 panel.addEventListener('pointerdown',gesture,{capture:true,passive:true});doc.addEventListener('visibilitychange',resume);win.addEventListener('pageshow',resume);win.addEventListener('focus',resume);
 const off=playback.subscribe(sync),offRuqyah=ruqyah.subscribe(sync),offTimer=playback.subscribeSleepTimer?.(drawTimer)||(()=>{});
 return()=>{disposed=true;stopLanguage();motion.destroy();off();offRuqyah();offTimer();offNature();nature.destroy();panel.removeEventListener('pointerdown',gesture,true);doc.removeEventListener('visibilitychange',resume);win.removeEventListener('pageshow',resume);win.removeEventListener('focus',resume);delete panel.dataset.nature;delete panel.dataset.natureVisual;const label=panel.querySelector('[data-nature-label]');if(label){label.textContent='';label.hidden=true;}root.remove();};
}
